INSERT IGNORE INTO categorias(nombre) VALUES ('Skateboards demo');
INSERT IGNORE INTO materiales(sku,nombre,descripcion,especificacion,unidad,categoria_id) SELECT v.sku,v.nombre,v.nombre,CONCAT(v.size_in,' pulgadas - deck'), 'unidad',c.id FROM (SELECT 'SK8-SUNSET-80' sku,'Sunset Bands' nombre,'8.0' size_in UNION ALL SELECT 'SK8-CHECKER-825','Checker Fade','8.25' UNION ALL SELECT 'SK8-KOI-80','Koi Pair','8.0' UNION ALL SELECT 'SK8-MARBLE-825','Marble Ink','8.25' UNION ALL SELECT 'SK8-CAT-80','Cat Eyes','8.0' UNION ALL SELECT 'SK8-TOPO-825','Topo Lines','8.25' UNION ALL SELECT 'SK8-FLAME-80','Flame Tail','8.0' UNION ALL SELECT 'SK8-HALFTONE-825','Halftone Wave','8.25') v JOIN categorias c ON c.nombre='Skateboards demo';
INSERT IGNORE INTO store_products(slug,name,description,product_type,collection_name,featured) VALUES ('sunset-bands','Sunset Bands','Deck de arce con bandas calidas y una silueta limpia para tu proxima sesion.','DECK','Coleccion de tablas',TRUE),('checker-fade','Checker Fade','Contraste clasico en una tabla versatil para calle y parque.','DECK','Coleccion de tablas',TRUE),('koi-pair','Koi Pair','Grafica de peces koi con acabado editorial y presencia en el riel.','DECK','Coleccion de tablas',TRUE),('marble-ink','Marble Ink','Tinta marmoleada para una tabla sobria y expresiva.','DECK','Coleccion de tablas',FALSE),('cat-eyes','Cat Eyes','Mirada felina y lineas precisas para una configuracion con caracter.','DECK','Coleccion de tablas',FALSE),('topo-lines','Topo Lines','Lineas topograficas inspiradas en mapas y movimiento.','DECK','Coleccion de tablas',FALSE),('flame-tail','Flame Tail','Fuego grafico en el tail para sesiones con energia.','DECK','Coleccion de tablas',FALSE),('halftone-wave','Halftone Wave','Olas y semitonos con una lectura retro contemporanea.','DECK','Coleccion de tablas',FALSE);
INSERT IGNORE INTO store_variants(product_id,material_id,sku,size_in,sale_price_crc,low_stock_threshold,specs_json) SELECT p.id,m.id,m.sku,v.size_in,v.price,2,JSON_OBJECT('material','Arce canadiense','ancho',v.size_in,'tipo','Deck') FROM (SELECT 'sunset-bands' slug,'SK8-SUNSET-80' sku,'8.0' size_in,28500 price UNION ALL SELECT 'checker-fade','SK8-CHECKER-825','8.25',29500 UNION ALL SELECT 'koi-pair','SK8-KOI-80','8.0',31000 UNION ALL SELECT 'marble-ink','SK8-MARBLE-825','8.25',32000 UNION ALL SELECT 'cat-eyes','SK8-CAT-80','8.0',30000 UNION ALL SELECT 'topo-lines','SK8-TOPO-825','8.25',30500 UNION ALL SELECT 'flame-tail','SK8-FLAME-80','8.0',29000 UNION ALL SELECT 'halftone-wave','SK8-HALFTONE-825','8.25',31500) v JOIN store_products p ON p.slug=v.slug JOIN materiales m ON m.sku=v.sku;
INSERT IGNORE INTO movimientos_stock(material_id,cantidad,tipo,ubicacion_destino_id,documento,motivo,idempotency_key) SELECT m.id,12,'APERTURA',u.id,'SKATE-DEMO-OPENING','Existencia inicial de demostracion',CONCAT('seed-skate-opening-',m.sku) FROM materiales m JOIN ubicaciones u ON u.codigo='BOD-CENTRAL' WHERE m.sku LIKE 'SK8-%';
INSERT IGNORE INTO store_settings(setting_key,setting_value) VALUES ('store_name','Skateboards'),('currency','CRC'),('store_contact','contacto@skateboards.local');
